local ADDON, ns = ...
local GCA, L = ns.GCA, ns.L
local UI = GCA.UI
local P = UI.P
local C, QualityColor, ItemName = P.C, P.QualityColor, P.ItemName

---------------------------------------------------------------------------
-- K7: where to get a recipe you don't know, from this addon's own data: Data/Sources.lua (ns.Sources, generated by
-- dev/gen_sources.lua: trainers, vendors with prices, quests, drops, NPC places) and Data/ExtraSources.lua (Forever
-- sources it lacks). No other addon is read. Every lookup is type-checked; missing data -> our coarse label.
-- Built per (profession, recipe), cached 30 s (the nearest NPC depends on where you stand).
---------------------------------------------------------------------------
local Src = { TTL = 30, cache = {}, at = nil }
UI.Src = Src
C.notLearned = "|cff9d9d9d" -- K7: the grey "Not learned" tag (the profession list greys unlearned recipes)
C.notLearnedTag = "|cffff4040" -- user 2026-11-15: the cards' "Not learned" button, red (grey wasn't visible enough)

local function Try(fn, ...)
  if type(fn) ~= "function" then return nil end
  local ok, a, b = pcall(fn, ...)
  if ok then return a, b end
  return nil
end
Src.Try = Try
-- info = { list = { sources: trainer, quest, vendor (incl. Merchant's Favor), drop / world / objects (RecipeSources.lua)
-- }, coarse = our src, skill, have = your rank (nil: you don't have the profession), sourced = our data knows the
-- recipe, scroll = pattern itemID, rep = { standing, name, met }, canWaypoint }
function Src.Build(prof, spellID, recipe)
  recipe = type(recipe) == "table" and recipe or {}
  local info = { list = {}, coarse = recipe.src or "other", skill = tonumber(recipe.skill) or 0 }
  local own = GCA:OwnProfessions()
  local mine = type(own) == "table" and own[prof]
  info.have = type(mine) == "table" and tonumber(mine.rank) or nil
  local RS = ns.RecipeSources
  info.sourced = type(RS) == "table" and RS.Collect(info, prof, spellID) or false
  local list = info.list
  if not info.sourced and info.coarse == "trainer" then list[1] = { kind = "trainer" } end
  -- Forever-only sources Data/Sources.lua lacks (Data/ExtraSources.lua): only when it knows no way to get the
  -- pattern; a vendor it knows without a price takes the price listed there for the same NPC
  local extra = ns.ExtraSources and ns.ExtraSources[spellID]
  local found = false
  for _, s in ipairs(list) do
    if s.kind ~= "trainer" then found = true end
    for _, e in ipairs(s.kind == "vendor" and not s.cost and s.npc and type(extra) == "table" and type(extra.v) == "table" and extra.v or {}) do
      if e[1] == s.npc.id then s.cost = tonumber(e[5]) end
    end
  end
  if type(extra) == "table" and not found then
    local function zoneOf(area, en)
      local z = area and C_Map and C_Map.GetAreaInfo and Try(C_Map.GetAreaInfo, area)
      if type(z) == "string" and z ~= "" then return z end
      return en
    end
    -- vendors (your faction's; side nil = both)
    local fac = UnitFactionGroup and Try(UnitFactionGroup, "player")
    local side = fac == "Alliance" and "A" or fac == "Horde" and "H" or nil
    local vs = {}
    for _, e in ipairs(type(extra.v) == "table" and extra.v or {}) do
      if not e[6] or not side or e[6] == side then
        vs[#vs + 1] = { id = e[1], name = e[2], zone = zoneOf(e[3], e[4]), cost = e[5] }
      end
    end
    if vs[1] then
      list[#list + 1] = { kind = "vendor", npc = vs[1], count = #vs, cost = vs[1].cost, extra = true }
    end
    -- drops
    if type(extra.d) == "table" and extra.d[1] then
      local s = { kind = "drop", count = #extra.d, npcs = {}, extra = true }
      for i = 1, math.min(#extra.d, 6) do
        local e = extra.d[i]
        local lv = (e[5] and e[6]) and (e[5] == e[6] and tostring(e[5]) or (e[5] .. "-" .. e[6])) or nil
        s.npcs[i] = { id = e[1], name = e[2], zone = zoneOf(e[3], e[4]), level = lv, pct = e[7] }
      end
      s.npc = s.npcs[1]
      list[#list + 1] = s
    end
    -- the pattern comes out of an item (localized name from the client when it has it)
    for _, e in ipairs(type(extra.c) == "table" and extra.c or {}) do
      local name = GetItemInfo and Try(GetItemInfo, e[1])
      list[#list + 1] = { kind = "container", name = (type(name) == "string" and name ~= "") and name or e[2], extra = true }
    end
  end
  for _, s in ipairs(list) do if s.npc and s.npc.map then info.canWaypoint = true end end
  return info
end

-- cached; an error anywhere -> the coarse info (never an error in the row or tooltip)
function Src.Get(prof, spellID, recipe)
  local now = GetTime()
  if not Src.at or now - Src.at > Src.TTL then Src.cache, Src.at = {}, now end
  local key = tostring(prof) .. ":" .. tostring(spellID)
  local v = Src.cache[key]
  if v == nil then
    local res = RavenquillExpedition:Call(Src.Build, prof, spellID, recipe)
    if type(res) == "table" then
      v = res
    else
      local rc = type(recipe) == "table" and recipe or {}
      v = { list = {}, coarse = rc.src or "other", skill = tonumber(rc.skill) or 0, failed = true }
      if v.coarse == "trainer" then v.list[1] = { kind = "trainer" } end
    end
    Src.cache[key] = v
  end
  return v
end
function Src.Reset() Src.cache, Src.at = {}, nil end

-- the sources of a suggestion's recipe; nil for a known recipe
function UI.SourceInfo(d, cur)
  if type(d) ~= "table" or d.known or type(d.cand) ~= "table" then return nil end
  local prof = cur and cur.prof or GCA:SelectedProfession()
  return Src.Get(prof, d.cand.spellID, d.cand.recipe)
end

-- one source as a short text: "Vendor: Androd Fadran (Arathi Highlands)", "Trainer (skill 170, you have 150)"
function Src.LineOf(s, info)
  local k = s.kind
  if k == "trainer" then
    local sk = info.skill or 0
    if info.have and sk > 0 then
      if info.have >= sk then return string.format(L.SRC_LINE_TRAINER_OK, sk) end
      return string.format(L.SRC_LINE_TRAINER_HAVE, sk, info.have)
    end
    return string.format(L.SRC_LINE_TRAINER, sk)
  elseif k == "vendor" then
    if not s.npc then return L.SRC_LINE_VENDOR_OTHER end
    local t = s.npc.zone and string.format(L.SRC_LINE_VENDOR, s.npc.name, s.npc.zone) or string.format(L.SRC_LINE_VENDOR_NOZONE, s.npc.name)
    if s.favor then t = t .. " · " .. string.format(L.SRC_LINE_FAVOR, s.favor) end
    return t
  elseif k == "quest" then
    if s.level and s.level > 0 then return string.format(L.SRC_LINE_QUEST_LVL, s.name, s.level) end
    return string.format(L.SRC_LINE_QUEST, s.name)
  elseif k == "drop" then
    local n = s.npc
    local name, zone = n and n.name or "?", n and n.zone or "?"
    if (s.count or 1) > 1 then return string.format(L.SRC_LINE_DROP_N, name, zone, s.count - 1) end
    return string.format(L.SRC_LINE_DROP, name, zone)
  elseif k == "world" then
    if s.levels then return string.format(L.SRC_LINE_WORLD_LVL, s.levels[1], s.levels[2]) end
    return L.SRC_LINE_WORLD
  elseif k == "objects" then
    return string.format(L.SRC_LINE_OBJECTS, s.count or 0)
  elseif k == "container" then
    return string.format(L.SRC_LINE_CONTAINER, s.name or "?")
  end
  return L.SRC_LINE_OTHER
end

-- the row's source line: the first (best) source + "+n more"; without any: the coarse label
function Src.Line(info)
  if type(info) ~= "table" then return nil end
  local list = info.list or {}
  local text
  if list[1] then
    text = Src.LineOf(list[1], info)
  else
    text = info.coarse == "pattern" and L.SRC_LINE_PATTERN or L.SRC_LINE_OTHER
  end
  if #list > 1 then text = text .. "  " .. C.muted .. string.format(L.SRC_LINE_MORE, #list - 1) .. "|r" end
  return text
end
function UI.SourceLine(d, cur) return Src.Line(UI.SourceInfo(d, cur)) end

local function Money(c)
  c = tonumber(c)
  if not c or c <= 0 then return nil end
  local s = Try(GetCoinTextureString, c)
  if type(s) == "string" and s ~= "" then return s end
  local g, si, k = math.floor(c / 10000), math.floor(c / 100) % 100, c % 100
  local parts = {}
  if g > 0 then parts[#parts + 1] = g .. "g" end
  if si > 0 then parts[#parts + 1] = si .. "s" end
  if k > 0 then parts[#parts + 1] = k .. "c" end
  return table.concat(parts, " ")
end
Src.Money = Money

-- "Arathi Highlands 45, 60" (coordinates only when our data has them)
local function Loc(n)
  if not n then return "" end
  if n.map then return string.format("%s %.0f, %.0f", n.zone or "", n.x * 100, n.y * 100) end
  return n.zone or ""
end
Src.Loc = Loc

-- The shared source tooltip body (user 2026-11-15: "the tooltip is very barebones ... move the prices into the
-- tooltip ... polish it"), used by the source button (cards, sheet, Gildenbedarf) and Gildenbedarf's source list:
--   Fundorte          [icon] Haendler: Androd Fadran          Arathihochland 45, 60
--                     [icon] Lehrer                           Fertigkeit 100 (erreicht)  (green / red)
--                          Name                                Zone 45, 60 (grey sub-line per NPC)
--   Preis             Beim Haendler 1g 20s / Beim Lehrer 50s / Im Auktionshaus 2g 50s (Auctionator, not BoP)
--   Muster / Ruf      the pattern item, the reputation it needs (green met / red not)
--   hints             two short blue lines (click / right-click), only when a source has coordinates
-- hints = { click = text, right = text } for the caller's own button; nil = the K7 default hint line.
local TIP_GOLD, TIP_GREY, TIP_WHITE = { 1, 0.82, 0 }, { 0.62, 0.62, 0.62 }, { 0.95, 0.95, 0.95 }
function Src.AddTooltip(info, hints)
  if type(info) ~= "table" then return end
  local T = GameTooltip
  local function dbl(l, r, lc, rc)
    lc, rc = lc or TIP_WHITE, rc or TIP_GREY
    T:AddDoubleLine(l, r or "", lc[1], lc[2], lc[3], rc[1], rc[2], rc[3])
  end
  local function sub(n)
    if n then dbl("     " .. n.name, Loc(n), TIP_GREY, TIP_GREY) end
  end
  T:AddLine(" ")
  T:AddLine(L.SRC_TIP_HEAD, TIP_GOLD[1], TIP_GOLD[2], TIP_GOLD[3])
  local vendorCost, trainerCost
  for _, s in ipairs(info.list or {}) do
    local icon = Src.Icon(s.kind) .. " "
    if s.kind == "trainer" then
      local right, rc = string.format(L.SRC_TIP_SKILL, info.skill or 0), TIP_GREY
      if info.have then
        if info.have >= (info.skill or 0) then
          right, rc = right .. " (" .. L.SRC_TIP_REACHED .. ")", { 0.3, 1, 0.3 }
        else
          right, rc = right .. " (" .. string.format(L.SRC_TIP_HAVE, info.have) .. ")", { 1, 0.35, 0.35 }
        end
      end
      dbl(icon .. (L.SRC_KIND_TRAINER:gsub("^%l", string.upper)), right, TIP_WHITE, rc)
      sub(s.npc)
      if (s.cost or 0) > 0 then trainerCost = math.min(trainerCost or s.cost, s.cost) end
    elseif s.kind == "vendor" then
      dbl(icon .. (s.npc and string.format(L.SRC_LINE_VENDOR_NOZONE, s.npc.name) or L.SRC_LINE_VENDOR_OTHER), Loc(s.npc))
      if s.favor then T:AddLine("     " .. string.format(L.SRC_LINE_FAVOR, s.favor), 0.4, 0.7, 1) end
      if (s.count or 0) > 1 then T:AddLine("     " .. string.format(L.SRC_TIP_VENDORS_MORE, s.count - 1), TIP_GREY[1], TIP_GREY[2], TIP_GREY[3]) end
      if (s.cost or 0) > 0 then vendorCost = math.min(vendorCost or s.cost, s.cost) end
    elseif s.kind == "quest" then
      dbl(icon .. Src.LineOf(s, info), nil, TIP_GOLD)
      sub(s.npc)
    elseif s.kind == "drop" then
      local npcs = s.npcs or {}
      for i, n in ipairs(npcs) do
        dbl((i == 1 and icon or "     ") .. string.format(L.SRC_TIP_DROP, n.name .. (n.level and (" (" .. n.level .. ")") or "")), Loc(n))
      end
      if #npcs == 0 then dbl(icon .. Src.LineOf(s, info)) end
      if (s.count or 0) > #npcs and #npcs > 0 then
        T:AddLine("     " .. string.format(L.SRC_TIP_DROPS_MORE, s.count - #npcs), TIP_GREY[1], TIP_GREY[2], TIP_GREY[3])
      end
    else
      dbl(icon .. Src.LineOf(s, info))
    end
  end
  if not (info.list and info.list[1]) then
    T:AddLine(info.sourced and L.SRC_TIP_UNKNOWN or Src.Line(info), TIP_GREY[1], TIP_GREY[2], TIP_GREY[3])
  end
  -- prices, named by where you pay them
  local ah = Src.PatternPrice(info)
  if vendorCost or trainerCost or ah then
    T:AddLine(" ")
    T:AddLine(L.PRICE_HEAD, TIP_GOLD[1], TIP_GOLD[2], TIP_GOLD[3])
    if vendorCost then dbl(L.PRICE_VENDOR, UI.Coins(vendorCost), TIP_WHITE, TIP_WHITE) end
    if trainerCost then dbl(L.PRICE_TRAINER, UI.Coins(trainerCost), TIP_WHITE, TIP_WHITE) end
    if ah then dbl(L.PRICE_AH, UI.Coins(ah), TIP_WHITE, TIP_WHITE) end
  end
  if info.scroll or info.rep then T:AddLine(" ") end
  if info.scroll then dbl(L.SRC_TIP_PATTERN_LABEL, ItemName(info.scroll), TIP_GREY, TIP_WHITE) end
  if info.rep then
    local ok = info.rep.met
    T:AddLine(string.format(L.SRC_TIP_REP, info.rep.standing, info.rep.name), ok and 0.3 or 1, ok and 1 or 0.35, ok and 0.3 or 0.35, true)
  end
  if info.canWaypoint then
    T:AddLine(" ")
    if hints then
      T:AddLine(hints.click, 0.5, 0.8, 1)
      T:AddLine(hints.right, 0.5, 0.8, 1)
    else
      T:AddLine(L.SRC_TIP_WAYPOINT, 0.5, 0.8, 1, true)
    end
  end
end

-- waypoint to an NPC: TomTom's arrow when it is installed (its public TomTom:AddWaypoint), else the client's user
-- waypoint + super-tracking, else the coordinates in chat; each guarded. Only for coordinates our data has
-- (n.map/x/y); none invented.
function Src.SetWaypoint(n)
  if not (type(n) == "table" and n.map and n.x and n.y) then return false end
  local tt = _G["TomTom"]
  local ok = type(tt) == "table" and type(tt.AddWaypoint) == "function"
    and pcall(tt.AddWaypoint, tt, n.map, n.x, n.y, { title = n.name, from = "Craft Advisor" })
  ok = ok or pcall(function()
    if not (C_Map and C_Map.SetUserWaypoint and UiMapPoint and UiMapPoint.CreateFromCoordinates) then error("no waypoint API") end
    if C_Map.CanSetUserWaypointOnMap and not C_Map.CanSetUserWaypointOnMap(n.map) then error("map refuses waypoints") end
    C_Map.SetUserWaypoint(UiMapPoint.CreateFromCoordinates(n.map, n.x, n.y))
    if C_SuperTrack and C_SuperTrack.SetSuperTrackedUserWaypoint then C_SuperTrack.SetSuperTrackedUserWaypoint(true) end
  end)
  GCA:Print(ok and string.format(L.SRC_WAYPOINT_SET, n.name, Loc(n)) or string.format(L.SRC_WAYPOINT_FAIL, n.name, Loc(n)))
  return ok and true or false
end

-- K14 (user: "jump to the location on the map"): waypoint + open the world map on the NPC's zone, so the pin is
-- right there. Map opening: OpenWorldMap(uiMapID) when the client has it, else WorldMapFrame + SetMapID; guarded
-- (in combat the map may refuse to open - the waypoint is set anyway).
function Src.ShowOnMap(n)
  if not (type(n) == "table" and n.map and n.x and n.y) then return false end
  local set = Src.SetWaypoint(n)
  local opened = false
  if type(OpenWorldMap) == "function" then opened = pcall(OpenWorldMap, n.map) end
  if not opened and WorldMapFrame then
    opened = pcall(function()
      if not WorldMapFrame:IsShown() then
        if ShowUIPanel then ShowUIPanel(WorldMapFrame) else WorldMapFrame:Show() end
      end
      if WorldMapFrame.SetMapID then WorldMapFrame:SetMapID(n.map) end
    end)
  end
  return set, opened
end

local KIND_WORD = { trainer = "SRC_KIND_TRAINER", vendor = "SRC_KIND_VENDOR", quest = "SRC_KIND_QUEST", drop = "SRC_KIND_DROP" }
-- right-click menu entries: a waypoint per source with coordinates
function Src.MenuEntries(info)
  local out = {}
  for _, s in ipairs(type(info) == "table" and info.list or {}) do
    local n = s.npc
    if n and n.map and KIND_WORD[s.kind] then
      out[#out + 1] = { label = string.format(L.SRC_MENU_WAYPOINT, n.name, L[KIND_WORD[s.kind]]), waypoint = n,
        fn = function() Src.ShowOnMap(n) end }
    end
  end
  return out
end

-- MenuUtil.CreateContextMenu (guarded); without it the first entry runs directly. false = nothing to offer.
function Src.Menu(owner, info, title)
  local entries = Src.MenuEntries(info)
  if #entries == 0 then return false end
  if MenuUtil and type(MenuUtil.CreateContextMenu) == "function" then
    local ok = pcall(MenuUtil.CreateContextMenu, owner, function(_, root)
      if title and root.CreateTitle then root:CreateTitle(title) end
      for _, e in ipairs(entries) do root:CreateButton(e.label, e.fn) end
    end)
    if ok then return true end
  end
  entries[1].fn()
  return true
end

-- row OnClick hook: a right-click is ours (also on known rows, so it never runs the left-click action);
-- the menu of map markers (user 2026-11-15: no "link the pattern in chat"). Returns true when the click was a right-click.
function UI.SourceClick(owner, button, d, cur)
  if button ~= "RightButton" then return false end
  local info = UI.SourceInfo(d, cur)
  if not info then return true end
  Src.Menu(owner, info, d.info and d.info.name)
  return true
end

-- User 2026-11-15: the "Not learned" tag on a card is a button. Hover = where to get the recipe (the source
-- tooltip block); click = a map marker on the source (one with coordinates: straight away; several: the menu);
-- right-click = the menu of all waypoints.
function UI.NotLearnedTip(owner, d, cur)
  if not d then return end
  GameTooltip:SetOwner(owner, "ANCHOR_RIGHT")
  local r, g, b = QualityColor(d.info and d.info.quality)
  GameTooltip:SetText(d.info and d.info.name or "?", r, g, b)
  GameTooltip:AddLine(L.NOT_LEARNED, 1, 0.35, 0.35)
  local info = UI.SourceInfo(d, cur)
  if info then Src.AddTooltip(info, { click = L.TIP_HINT_MAP, right = L.TIP_HINT_MENU }) end
  GameTooltip:Show()
end
-- User 2026-11-15: the card's "Not learned" button shows the best source straight away: an icon for its kind
-- (trainer / vendor / quest / mob drop / world drop / chest / pattern) + the source line ("Lehrer (Fertigkeit 100)",
-- "+n weitere"), and for a BoE pattern Auctionator's price of the pattern. Without source data: "Not learned".
Src.KIND_ICON = {
  trainer = "Interface\\GossipFrame\\TrainerGossipIcon",
  vendor = "Interface\\GossipFrame\\VendorGossipIcon",
  quest = "Interface\\GossipFrame\\AvailableQuestIcon",
  drop = "Interface\\TargetingFrame\\UI-TargetingFrame-Skull",
  world = "Interface\\Icons\\INV_Misc_Map_01",
  objects = "Interface\\Icons\\INV_Box_02",
  container = "Interface\\Icons\\INV_Box_02",
  other ="Interface\\Icons\\INV_Scroll_03",
}
function Src.Icon(kind)
  local path = Src.KIND_ICON[kind] or Src.KIND_ICON.other
  if path:find("\\Icons\\", 1, true) then return "|T" .. path .. ":14:14:0:0:64:64:5:59:5:59|t" end
  return "|T" .. path .. ":14:14|t"
end
-- Auctionator's price of a pattern that can be bought (not BoP); nil when there is none / no Auctionator
function Src.PatternPrice(info)
  local A = GCA.Auction
  if not (type(info) == "table" and info.scroll and A and A.Available()) then return nil end
  local si = GCA:GetInfo(info.scroll)
  if si and si.bind == 1 then return nil end
  return A.AuctionPrice(info.scroll)
end
function UI.SourceBadge(d, cur)
  local info = UI.SourceInfo(d, cur)
  local first = info and info.list and info.list[1]
  local kind = first and first.kind or (info and info.coarse == "pattern" and "other") or nil
  if not info or (not first and not info.scroll) then return nil end
  -- (prices are in the tooltip, user 2026-11-15)
  return Src.Icon(kind) .. " " .. (Src.Line(info) or L.NOT_LEARNED)
end
function UI.NotLearnedClick(owner, button, d, cur)
  local info = d and UI.SourceInfo(d, cur)
  if not info then return end
  if button ~= "RightButton" then
    local wps = {}
    for _, e in ipairs(Src.MenuEntries(info)) do if e.waypoint then wps[#wps + 1] = e end end
    if #wps == 1 then wps[1].fn(); return end
  end
  Src.Menu(owner, info, d.info and d.info.name)
end

-- shared with the files loaded after this one (P)
P.Src = Src
